{
  "requirements": [
    {
      "id": "F-01",
      "text": "The system shall implement a multi-layer safety architecture including passive, active, and functional safety mechanisms to ensure collision protection and fail-safe operations.",
      "quality_axes": ["Safety", "Efficiency", "Trustworthiness", "Responsibility"],
      "derived_from": ["SAF-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-02",
      "text": "The system shall execute a Minimal Risk Maneuver within defined guidelines upon detecting critical system failures to safely pull over to a low-risk zone.",
      "quality_axes": ["Safety", "Efficiency", "Responsibility"],
      "derived_from": ["SAF-02", "EFF-03"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-03",
      "text": "The system shall continuously monitor Operational Design Domain compliance and provide timely human takeover requests when boundaries are approached.",
      "quality_axes": ["Safety", "Responsibility"],
      "derived_from": ["SAF-03", "EFF-04"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-04",
      "text": "The system shall minimize jerk during normal operation and emergency maneuvers, ensuring both passenger comfort and safety.",
      "quality_axes": ["Safety", "Efficiency"],
      "derived_from": ["SAF-04", "EFF-07"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-05",
      "text": "The system shall satisfy curvature constraints to prevent rollover during maneuvers at all speeds.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-05"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-06",
      "text": "The system shall utilize iterative quadratic programming to handle non-convex obstacle constraints with a processing time under 50 milliseconds.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["SAF-06", "EFF-06"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-07",
      "text": "The system shall ensure that energy consumption targets are integrated in performance optimizations during travel time reductions.",
      "quality_axes": ["Efficiency", "Sustainability"],
      "derived_from": ["EFF-01", "GRN-01"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-08",
      "text": "The system shall provide transparent logging of decisions made during emergency maneuvers for accountability and safety.",
      "quality_axes": ["Trustworthiness", "Responsibility"],
      "derived_from": ["TRU-03", "RES-07"],
      "kaos_level": "operational",
      "parent": "F-01"
    }
  ],
  "conflict_resolutions": [
    {
      "ids": ["EFF-01", "GRN-01"],
      "outcome": "merged",
      "favored_agent": null,
      "rationale": "Travel time reduction and energy efficiency metrics were combined to ensure performance does not increase emissions."
    },
    {
      "ids": ["EFF-03", "SAF-02"],
      "outcome": "decomposed",
      "favored_agent": null,
      "rationale": "Flexibility in execution timing was allowed under strict guidelines to ensure safety without compromising performance."
    },
    {
      "ids": ["EFF-07", "SAF-04"],
      "outcome": "merged",
      "favored_agent": null,
      "rationale": "Smoothness considerations during emergencies were integrated with safety requirements."
    }
  ],
  "dropped": [
    {
      "id": "SAF-07",
      "reason": "The emergency protocols proposed were integrated into other requirements and thus not needed separately."
    },
    {
      "id": "EFF-02",
      "reason": "This requirement was effectively covered by the minimization of jerk during operations."
    },
    {
      "id": "GRN-02",
      "reason": "This sustainability requirement was not directly addressed in the final integrated requirements."
    },
    {
      "id": "GRN-03",
      "reason": "Lifecycle assessments were not included as they did not directly influence the final requirements."
    },
    {
      "id": "GRN-04",
      "reason": "Energy recovery efficiency was not specifically targeted in favor of broader performance metrics."
    },
    {
      "id": "GRN-05",
      "reason": "Real-time carbon emissions monitoring was not included in the final requirements."
    },
    {
      "id": "GRN-06",
      "reason": "Energy-efficient routing algorithms were not specifically included as they were covered by other operational metrics."
    },
    {
      "id": "GRN-07",
      "reason": "Emergency protocols minimizing energy usage did not make it into the final requirements."
    },
    {
      "id": "TRU-01",
      "reason": "End-to-end data encryption was not included as a specific requirement but was implied in overall requirements."
    },
    {
      "id": "TRU-02",
      "reason": "Role-based access control was integrated into broader safety and trust measures."
    },
    {
      "id": "TRU-04",
      "reason": "Data anonymization techniques were not explicitly stated in the final requirements."
    },
    {
      "id": "TRU-05",
      "reason": "Regular security audits were not included as part of the operational requirements."
    },
    {
      "id": "TRU-06",
      "reason": "Secure remote software updates were implicitly covered by the trust and safety logging requirements."
    },
    {
      "id": "TRU-07",
      "reason": "User interface requirements were not included as they were not deemed critical."
    },
    {
      "id": "RES-01",
      "reason": "Compliance with specifications was integrated into broader safety requirements."
    },
    {
      "id": "RES-02",
      "reason": "Active monitoring and response were effectively covered by the multi-layer safety architecture."
    },
    {
      "id": "RES-04",
      "reason": "Continuous monitoring of ODD compliance was included in the logging and monitoring requirements."
    },
    {
      "id": "RES-05",
      "reason": "Timely HMI warnings were integrated into operational requirements."
    },
    {
      "id": "RES-06",
      "reason": "Prioritizing passenger safety was encapsulated within the final requirements on safety."
    }
  ],
